def _side_closure(
    start: FieldId,
    adjacency: Dict[FieldId, List[FieldId]],
    edge_ids: Set[EdgeId],
) -> Tuple[Set[FieldId], Set[EdgeId]]:
    """Reachable fields and the edges whose endpoints are both reachable."""
    reachable = _reachable(start, adjacency)
    induced = {
        edge
        for edge in edge_ids
        if edge[0] in reachable and edge[1] in reachable
    }
    return reachable, induced

